begin;
update business_private.email_settings set sending_enabled=true,daily_limit=10,monthly_limit=100,day_used=0,month_used=0,capacity_verified_until=now()+interval '1 hour';
update business_private.email_outbox set status='cancelled',lease_token=null;
update business_private.applications set state='approved',revision=10;
select pg_temp.event(10,'approve');
select set_config('test.email.claim',business_private.claim_application_email()::text,false);
select pg_temp.ok(business_private.authorize_application_email((current_setting('test.email.claim')::jsonb->>'id')::uuid,(current_setting('test.email.claim')::jsonb->>'lease_token')::uuid)->>'kind'='approve','current approval authorizes exact claimed message');
select pg_temp.ok(business_private.authorize_application_email((current_setting('test.email.claim')::jsonb->>'id')::uuid,(current_setting('test.email.claim')::jsonb->>'lease_token')::uuid) is null,'dispatch authorization is one use');
update business_private.applications set revision=11;
select pg_temp.event(11,'approve');
select set_config('test.email.claim',business_private.claim_application_email()::text,false);
update business_private.applications set state='changes_requested',revision=12;
select pg_temp.ok(business_private.authorize_application_email((current_setting('test.email.claim')::jsonb->>'id')::uuid,(current_setting('test.email.claim')::jsonb->>'lease_token')::uuid) is null,'reopened approval cannot send old finish-setup message');
select pg_temp.ok((select status='cancelled' from business_private.email_outbox where revision=11),'stale decision is cancelled not retried');
update business_private.applications set state='approved',revision=13;
select pg_temp.event(13,'approve');
select set_config('test.email.claim',business_private.claim_application_email()::text,false);
select pg_temp.ok(business_private.authorize_application_email((current_setting('test.email.claim')::jsonb->>'id')::uuid,gen_random_uuid()) is null,'wrong dispatch token rejected');
update business_private.email_settings set capacity_verified_until=now()-interval '1 second';
select pg_temp.ok(business_private.authorize_application_email((current_setting('test.email.claim')::jsonb->>'id')::uuid,(current_setting('test.email.claim')::jsonb->>'lease_token')::uuid) is null,'capacity expiry after claim stops dispatch');
select pg_temp.ok(not has_function_privilege('authenticated','business_private.authorize_application_email(uuid,uuid)','execute'),'member cannot authorize mail');
select pg_temp.ok(not has_function_privilege('doji_identity_resolver','business_private.authorize_application_email(uuid,uuid)','execute'),'portal runtime cannot authorize mail');
rollback;
